from datetime import datetime
from typing import Any, Dict, List, Literal, Optional, Union
from pydantic import BaseModel, Field

class RiskStratification(BaseModel):
    """Categorical risk assessment with clinical decision support disclaimer."""
    risk_level: Literal["LOW", "MEDIUM", "HIGH"]
    score: float
    medical_disclaimer: str = (
        "This result is generated by a machine-learning research prototype and "
        "is not a medical diagnosis."
    )

class ModelRecommendation(BaseModel):
    training_run_id: str
    model_type: str
    recommendation_score: float
    metrics: Dict[str, float]
    reason: str

class DatasetOption(BaseModel):
    dataset_id: str
    name: str

class TrainedModelOption(BaseModel):
    training_run_id: str
    model_type: str
    preprocessing_run_id: Optional[str]
    metrics: Dict[str, Any]
    features_count: int

class FeatureSchema(BaseModel):
    name: str
    type: Literal["categorical", "numerical", "binary"]
    categories: Optional[List[str]] = None
    min_value: Optional[float] = None
    max_value: Optional[float] = None
    description: str = ""

class PredictionSchemaResponse(BaseModel):
    training_run_id: str
    features: List[FeatureSchema]

class PredictionRequest(BaseModel):
    """Payload for real-time model inference."""
    training_run_id: str
    patient_data: Dict[str, Any] = Field(
        ...,
        description="Patient biomarker readings mapped by feature name."
    )
    threshold: Optional[float] = Field(default=0.5, ge=0.0, le=1.0)

class SinglePredictionResult(BaseModel):
    """Single sample prediction output."""
    training_run_id: str
    dataset_id: str
    model_type: str
    score: float
    threshold: float
    prediction: int
    predicted_label: str
    risk_category: str
    explanation: Optional[Dict[str, Any]] = None

class RecommendModelRequest(BaseModel):
    dataset_id: str
